// ID smuggled into the query string; missing param throws because it's required by default
@GetMapping("/users")           // GET /users?id=123  (not RESTful)
User get(@RequestParam Long id) { return service.findById(id); }

@GetMapping("/search")          // GET /search  (no q) -> 400, param is required
List<User> search(@RequestParam String q) { return service.search(q); }
